begin;
select plan(12);
insert into auth.users (id,email) values ('11111111-1111-1111-1111-111111111111','assistant-a@test.local'),('22222222-2222-2222-2222-222222222222','assistant-b@test.local');
set local role authenticated;
set local request.jwt.claims to '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}';
insert into public.agent_tool_approvals(user_id,turn_key,tool_call_id,tool_name,input,preview,targets) values ('11111111-1111-1111-1111-111111111111','turn','approval-rls','tasks.delete','{}','{}','[]');
insert into public.assistant_suggestions(id,user_id,dedupe_key,kind,title,body,href) values ('aaaaaaaa-0000-0000-0000-000000000010','11111111-1111-1111-1111-111111111111','a','time_conflict','A','A','/today');
insert into public.assistant_preference_corrections(user_id,correction_key,preference_key,value,evidence) values ('11111111-1111-1111-1111-111111111111','a','defaultDurationMinutes',30,'{}');
insert into public.notification_controls(user_id) values ('11111111-1111-1111-1111-111111111111');
insert into public.notification_deliveries(user_id,dedupe_key,kind,local_date) values ('11111111-1111-1111-1111-111111111111','a','proactive','2026-09-05');
select is((select count(*) from public.agent_tool_approvals),1::bigint,'Owner sees own proposal');
set local request.jwt.claims to '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}';
select is((select count(*) from public.agent_tool_approvals),0::bigint,'Other user cannot see approvals');
select is((select count(*) from public.assistant_suggestions),0::bigint,'Other user cannot see suggestions');
select is((select count(*) from public.assistant_preference_corrections),0::bigint,'Other user cannot see preference evidence');
select is((select count(*) from public.notification_controls),0::bigint,'Other user cannot see notification settings');
select is((select count(*) from public.notification_deliveries),0::bigint,'Other user cannot see delivery records');
with changed as (update public.agent_tool_approvals set status='approved' returning id) select is((select count(*) from changed),0::bigint,'Other user cannot approve');
with changed as (delete from public.assistant_suggestions returning id) select is((select count(*) from changed),0::bigint,'Other user cannot dismiss suggestions');
select throws_ok($$ insert into public.notification_controls(user_id) values ('11111111-1111-1111-1111-111111111111') $$,'42501',null,'Cannot forge owner');
select throws_ok($$ select public.claim_notification_delivery('11111111-1111-1111-1111-111111111111','forged','proactive',now(),'Asia/Seoul',null) $$,'P0001','not authorized','Cannot claim another user delivery');
select throws_ok($$ select public.set_notification_suggestion_kind('11111111-1111-1111-1111-111111111111','time_conflict',false) $$,'P0001','not authorized','Cannot disable another user suggestion');
select throws_ok($$ select public.resolve_preference_suggestion('aaaaaaaa-0000-0000-0000-000000000010','11111111-1111-1111-1111-111111111111',true,now()) $$,'P0001','not authorized','Cannot accept another user preference');
select * from finish();
rollback;
